@Test
void killOrderServicePlaceOrderGoodsCalculationDiscountSubtraction() {
    OrderService orderService = new OrderService();
    Cart cart = new Cart();
    // Subtotal = 500,000 VND
    Product product = new Product("P1", "Product 1", 500_000L, 500, 5);
    cart.addItem(product, 1);

    // Discount = 1,000 VND -> goods = 500,000 - 1,000 = 499,999 VND (< 500,000 -> not eligible for free shipping)
    // If mutant changes to addition: goods = 501,000 VND (>= 500,000 -> shipping becomes 0)
    Coupon coupon = new Coupon("FIXED1K", CouponType.FIXED, 1_000L, 0L, 0L, LocalDate.of(2026, 11, 25));
    LocalDateTime now = LocalDateTime.of(2026, 11, 23, 8, 0, 0);

    Order order = orderService.placeOrder("ORD-GOODS-SUB", cart, coupon, Region.INNER_CITY, now);
    assertEquals(15_000L, order.getShipping());
    assertEquals(514_999L, order.getTotal());
}
