@Test
void testOrderConstructorDefensiveCopyAndUnmodifiableItems() {
    Product p = new Product("P1", "Product 1", 10000, 100, 10);
    CartItem item1 = new CartItem(p, 1);
    List<CartItem> mutableList = new ArrayList<>();
    mutableList.add(item1);
    LocalDateTime now = LocalDateTime.of(2026, 11, 23, 8, 0);

    Order order = new Order("D-IMMUTABLE", mutableList, 10000, 0, 15000, 25000, now, Region.INNER_CITY);

    // Modifying the source list does not affect the order items
    mutableList.add(new CartItem(p, 1));
    assertEquals(1, order.getItems().size());

    // Modifying the returned items list must throw UnsupportedOperationException
    assertThrows(UnsupportedOperationException.class, () ->
        order.getItems().add(new CartItem(p, 1))
    );
}
