@Test
void testPlaceOrderFailsWhenSubsequentItemHasInsufficientStockAndDoesNotDeductPriorItem() {
    OrderService service = new OrderService();
    Product p1 = new Product("P1", "Product 1", 10000, 100, 5);
    Product p2 = new Product("P2", "Product 2", 20000, 100, 1);

    Cart cart = new Cart();
    cart.addItem(p1, 2); // needs 2, p1 has 5
    cart.addItem(p2, 1); // cart has 1, but we reduce stock manually to test stock failure during placeOrder
    p2.reduceStock(1);   // p2 stock is now 0 < 1

    LocalDateTime now = LocalDateTime.of(2026, 11, 23, 8, 0);

    assertThrows(InsufficientStockException.class, () ->
        service.placeOrder("ORD-FAIL-STOCK", cart, null, Region.INNER_CITY, now)
    );

    // Prior item p1 must NOT have its stock deducted
    assertEquals(5, p1.getStock());
    assertEquals(0, p2.getStock());
}
```

