@Test
void testCancelShippedOrCancelledOrderThrowsIllegalStateExceptionPriorToTimeCheck() {
    OrderService service = new OrderService();
    Product p = new Product("P1", "Product 1", 10000, 100, 5);
    Cart cart = new Cart();
    cart.addItem(p, 1);

    LocalDateTime createdAt = LocalDateTime.of(2026, 11, 23, 8, 0, 0);
    Order order = service.placeOrder("ORD-SHIPPED-FAIL", cart, null, Region.INNER_CITY, createdAt);
    service.pay(order);
    service.ship(order);

    // Providing a timestamp earlier than createdAt
    LocalDateTime earlierTime = LocalDateTime.of(2026, 11, 23, 7, 0, 0);

    // Rule 2 states: SHIPPED or CANCELLED throws IllegalStateException before checking datetime
    assertThrows(IllegalStateException.class, () ->
        service.cancelOrder(order, earlierTime)
    );
    assertEquals(OrderStatus.SHIPPED, order.getStatus());
}
```

